-- Scaffold generated by SMELTER from frozen contract predator-system-v1.
-- The constructor validation and method shapes match the contract interface.
-- Fill in ONE helper at a time (search for TODO), then run the tests.
-- Passive module: only declared imports; no os, io, print, _G or module-level mutable state.
local Adapter = require("engine_adapter")
local Predator = require("predator_controller")
local Policy = require("entity_policy")
local M = {}

function M.new(deps)
  if type(deps) ~= "table" then
    return nil, "deps_not_table"
  end

  -- Per-instance state lives here, never at module level.
  local state = {}
  local controller = {}

  local provider = deps.adapter
  if provider == nil then provider = deps.runtime end
  local adapter, why = Adapter.new(provider)
  if not adapter then return nil, why end
  local function make_controller()
    return Predator.new({adapter = adapter, evaluate = Policy.evaluate,
      clock = deps.clock, profile = deps.profile, policy = deps.policy})
  end
  local validated, invalid = make_controller()
  if not validated then return nil, invalid end

  -- Reject nonstring/empty id and existing state[id].
  -- Create a fresh c,why = make_controller(); reject nil; state[id]=c; return true.
  -- add_actor returns true or nil, nonempty reason
  function controller:add_actor(id)
    if type(id) ~= "string" or id == "" then
      return nil, "invalid_id"
    end
    if state[id] then
      return nil, "already_registered"
    end
    local c, why = make_controller()
    if not c then return nil, why end
    state[id] = c
    return true
  end

  -- Unknown state[id]: return nil,unknown_actor without stop.
  -- local ok,value,why = pcall(adapter.stop,id); reject throw or nil/false, retaining state[id].
  -- Only on admitted stop: state[id]=nil and return true.
  -- remove_actor returns true or nil, nonempty reason; refuse keeps state[id]
  function controller:remove_actor(id)
    if not state[id] then
      return nil, "unknown_actor"
    end
    local ok, value, why = pcall(adapter.stop, id)
    if not ok then
      return nil, "adapter_error:" .. tostring(value)
    end
    if value == nil or value == false then
      return nil, "adapter_refused:" .. tostring(why)
    end
    state[id] = nil
    return true
  end

  -- For each id,c in pairs(state), pcall(c.update,c,id).
  -- Put a returned result table in results[id]; on throw/non-table put action=error with nonempty reason.
  -- Continue all actors and return results. Do not call module-level Predator.update.
  -- tick returns table keyed by actor ID
  function controller:tick()
    local results = {}
    for id, c in pairs(state) do
      local ok, value = pcall(c.update, c, id)
      if ok and type(value) == "table" then
        results[id] = value
      else
        results[id] = {action = "error", reason = "controller_error:" .. tostring(value)}
      end
    end
    return results
  end

  return controller
end

return M
